总计
\(O((n+q) \log n)\)



空间复杂度 \(O(n+q)\)。

六、AC code
#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int N = 3e5 + 5;

ll n, q;
ll t[N], b[N];

ll nxt[N], lst[N];
ll ans[N];

struct node {
	ll r, id;
};

struct NODE {
	ll l, r;
	ll maxv, tag;
};
NODE tr[N * 4];

void pushdown (int p) {
	if (tr[p].tag) {
		tr[p * 2].maxv += tr[p].tag;
		tr[p * 2 + 1].maxv += tr[p].tag;
		tr[p * 2].tag += tr[p].tag;
		tr[p * 2 + 1].tag += tr[p].tag;
		tr[p].tag = 0;
	}
}

void pushup (int p) {
	tr[p].maxv = max (tr[p * 2].maxv, tr[p * 2 + 1].maxv);
}

void build (int p, int l, int r) {
	tr[p].l = l, tr[p].r = r;
	tr[p].maxv = 0, tr[p].tag = 0;

	if (l == r) return;

	int mid = (l + r) / 2;
	build (p * 2, l, mid);
	build (p * 2 + 1, mid + 1, r);
}

void change (int p, int l, int r) {
	if (tr[p].l >= l && tr[p].r <= r) {
		tr[p].maxv += 1;
		tr[p].tag += 1;
		return;
	}

	pushdown (p);

	int mid = (tr[p].l + tr[p].r) / 2;

	if (l <= mid) change (p * 2, l, r);
	if (r > mid) change (p * 2 + 1, l, r);

	pushup (p);
}

ll query (int p, int l, int r) {
	if (tr[p].l >= l && tr[p].r <= r) return tr[p].maxv;

	pushdown (p);

	int mid = (tr[p].l + tr[p].r) / 2;
	ll res = 0;

	if (l <= mid) res = max (res, query (p * 2, l, r) );
	if (r > mid) res = max (res, query (p * 2 + 1, l, r) );

	return res;
}

int main () {
	freopen("login.in", "r", stdin);
	freopen("login.out", "w", stdout);

	ios::sync_with_stdio (false);
	cin.tie (0);

	cin >> n >> q;

	for (int i = 1; i <= n; i ++) {
		cin >> t[i] >> b[i];
	}

	vector<vector<node> > que (n + 1);

	for (int i = 1; i <= q; i ++) {
		ll l, r;
		cin >> l >> r;

		que[l].push_back ({ r, i });
	}

	for (int i = n; i >= 1; i --) {
		if (!lst[b[i]]) nxt[i] = n + 1;
		else nxt[i] = lst[b[i]];

		lst[b[i]] = i;
	}

	build(1, 1, n);

	for (int l = n; l >= 1; l --) {
		if (t[l] == 1) change (1, l, nxt[l] - 1);

		for (auto &[r, id] : que[l]) {
			ans[id] = query (1, l, r);
		}
	}

	for (int i = 1; i <= q; i ++) cout << ans[i] << '\n';

	return 0;
}



总结


历史最值转区间最值；


定一求一按左端点扫描；


在线区间并集
